//! The real-part benchmarks (parts/bench/*.fg), for the speed and bit gate:
//!   benchfg bits      each part's exact result hashed: the features its .fg run sends, regenerated
//!                        by the kernel in sequence and in n-ary booleans
//!   benchfg replay    each part regenerated by the kernel alone from its .fg features and ids
//!   benchfg check     each part built: features, faces, edges and the build's time
use forge_math::hash::BitHasher;

const NAMES: [&str; 15] = [
    "bracket", "clamp", "conrod", "crank", "frame", "gearbox", "guard", "heatsink", "hub", "insert", "jack",
    "manifold", "quadarm", "valve", "volute",
];

/// Part `name`'s .fg run, the bench font beside it, and the time it took (ms).
fn build(name: &str) -> (forge_lang::Run, f64, forge_model::Part, Vec<u64>) {
    let dir = std::env::temp_dir().join(format!("forge-benchfg-{}", std::process::id()));
    std::fs::create_dir_all(&dir).expect("temp dir");
    let font = dir.join(forge_agent::bench::FONT);
    if !font.exists() {
        std::fs::write(&font, forge_agent::bench::font_bytes()).expect("font");
    }
    let path = format!("{}/parts/bench/{name}.fg", env!("CARGO_MANIFEST_DIR"));
    let src = std::fs::read_to_string(&path).expect("part file");
    let opts = forge_lang::Options {
        dir: Some(dir),
        ..forge_lang::Options::default()
    };
    let t = std::time::Instant::now();
    let (run, cache) = forge_lang::run(&src, opts, Default::default());
    let ms = t.elapsed().as_secs_f64() * 1e3;
    assert!(
        run.errors.is_empty(),
        "{name}: {}",
        forge_lang::report::text(&run, &src)
    );
    let (f, ids) = cache.history();
    let part = forge_model::Part { features: f.to_vec() };
    (run, ms, part, ids.to_vec())
}

fn main() {
    let what = std::env::args().nth(1).unwrap_or_default();
    if what != "bits" && what != "check" && what != "replay" {
        eprintln!("usage: benchfg bits | check");
        std::process::exit(2);
    }
    for name in NAMES {
        let (run, ms, part, ids) = build(name);
        let b = run.body.as_ref().expect("a body");
        if what == "bits" {
            // the kernel's own regens of the features the run sent, named by their ids: in
            // sequence and in n-ary booleans (4 threads), as the .fc bench was
            for (path, r) in [
                ("seq", part.regenerate_solids_ids(Some(&ids))),
                ("nary", part.regenerate_nary_solids_ids(4, Some(&ids))),
            ] {
                let mut h = BitHasher::new();
                match r {
                    Ok(solids) => {
                        for b in solids.iter().map(|s| &s.body) {
                            for v in &b.vertices {
                                h.p3(v.point);
                            }
                            for e in &b.edges {
                                h.f64(e.range.lo);
                                h.f64(e.range.hi);
                            }
                            h.u64(b.faces.len() as u64);
                        }
                    }
                    Err(_) => h.u64(u64::MAX),
                }
                println!("{name} {path} {:016x}", h.finish());
            }
        } else if what == "replay" {
            let seq = part.regenerate_solids_ids(Some(&ids));
            let nary = part.regenerate_nary_solids_ids(4, Some(&ids));
            println!(
                "{name}: nary {}",
                match &nary {
                    Ok(_) => "ok".to_string(),
                    Err(e) => format!("FAILED {e:?}"),
                }
            );
            println!(
                "{name}: replay {}",
                match &seq {
                    Ok(s) => format!(
                        "ok, {} faces",
                        s.iter().map(|x| x.body.faces.len()).sum::<usize>()
                    ),
                    Err(e) => format!("FAILED {e:?}"),
                }
            );
        } else {
            println!(
                "{name}: {} features, {} faces, {} edges, built in {ms:.0} ms",
                run.feats.len(),
                b.faces.len(),
                b.edges.len()
            );
        }
    }
}
